package com.vault.config;
import com.vault.security.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.http.HttpMethod;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.web.*;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.cors.*;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.*;
@Configuration public class SecurityConfig{
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
 @Bean SecurityFilterChain chain(HttpSecurity http,JwtService jwt,UserDetailsService users,@Value("${app.cors.allowed-origin}")String origin)throws Exception{return http.csrf(c->c.disable()).cors(c->c.configurationSource(r->{var x=new CorsConfiguration();x.setAllowedOrigins(List.of(origin));x.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));x.setAllowedHeaders(List.of("Authorization","Content-Type"));return x;})).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint((req,res,ex)->{res.setStatus(401);res.setContentType("application/json");res.getWriter().write("{\"message\":\"Authentication required\"}");})).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**").permitAll().requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().anyRequest().authenticated()).addFilterBefore(new JwtFilter(jwt,users),UsernamePasswordAuthenticationFilter.class).build();}
 static class JwtFilter extends OncePerRequestFilter{private final JwtService jwt;private final UserDetailsService users;JwtFilter(JwtService jwt,UserDetailsService users){this.jwt=jwt;this.users=users;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var user=users.loadUserByUsername(jwt.subject(h.substring(7)));var auth=new UsernamePasswordAuthenticationToken(user,null,user.getAuthorities());org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(auth);}catch(RuntimeException ignored){}c.doFilter(r,s);}}
}
